begin transaction isolation level repeatable read read only; select jsonb_build_object('at',now(),'database',current_database(),'role',current_user,'work',(select to_jsonb(w) from public.works w where id=959100031),'edition',(select to_jsonb(e) from public.editions e where id=959200031),'foreignKeys',(select coalesce(jsonb_agg(jsonb_build_object('name',f.conname,'schema',ns.nspname,'relation',c.relname,'parent',p.relname,'deleteAction',f.confdeltype,'columns',(select jsonb_agg(jsonb_build_object('child',ca.attname,'parent',pa.attname) order by k.ord) from unnest(f.conkey,f.confkey) with ordinality k(childkey,parentkey,ord) join pg_attribute ca on ca.attrelid=f.conrelid and ca.attnum=k.childkey join pg_attribute pa on pa.attrelid=f.confrelid and pa.attnum=k.parentkey)) order by ns.nspname,c.relname,f.conname),'[]') from pg_constraint f join pg_class c on c.oid=f.conrelid join pg_namespace ns on ns.oid=c.relnamespace join pg_class p on p.oid=f.confrelid where f.contype='f' and f.confrelid in ('public.works'::regclass,'public.editions'::regclass)),'relatedColumns',(select coalesce(jsonb_agg(jsonb_build_object('table',table_name,'column',column_name,'type',data_type) order by table_name,column_name),'[]') from information_schema.columns where table_schema='public' and column_name in ('work_id','edition_id','book_id','parent_work_id','parent_id','target_work_id','recommended_work_id')),'triggers',(select coalesce(jsonb_agg(jsonb_build_object('name',t.tgname,'relation',t.tgrelid::regclass::text,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid))),'[]') from pg_trigger t where not t.tgisinternal and t.tgrelid in ('public.works'::regclass,'public.editions'::regclass)),'rules',(select coalesce(jsonb_agg(to_jsonb(r)),'[]') from pg_rules r where schemaname='public' and tablename in ('works','editions')),'sequences',(select coalesce(jsonb_agg(jsonb_build_object('schema',schemaname,'name',sequencename,'last',last_value,'increment',increment_by,'cycle',cycle) order by sequencename),'[]') from pg_sequences where schemaname='public')) as preflight; rollback;
